begin;
set local role postgres;
create extension if not exists pgtap with schema extensions;
select extensions.plan(12);
select extensions.ok((select count(*)=7 and bool_and(not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('service_role',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('schedule_template_productions','list_schedule_templates','read_schedule_template','mutate_schedule_template','check_schedule_template_request','list_organization_templates','publish_schedule_template')), 'All template entrypoints reject anonymous and service-role execution');
select extensions.ok((select count(*)=7 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('schedule_template_productions','list_schedule_templates','read_schedule_template','mutate_schedule_template','check_schedule_template_request','list_organization_templates','publish_schedule_template')), 'Template entrypoints admit authenticated calls with server authorization');
select extensions.ok((select count(*)=15 and bool_and(not has_function_privilege(r.name,p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join (values('anon'),('authenticated'),('service_role')) r(name) where n.nspname='private' and p.proname in ('template_production_actor_can','template_actor_can','template_publication_source_readable','template_actor_can_publish','withdraw_changed_template_publication')), 'Private authorization and publication trigger functions cannot be called by clients');
select extensions.ok((select count(*)=9 and bool_and(not has_table_privilege(r.name,t.name,'SELECT,INSERT,UPDATE,DELETE')) from (values('private.schedule_templates'),('private.schedule_template_sources'),('private.schedule_template_receipts')) t(name) cross join (values('anon'),('authenticated'),('service_role')) r(name)), 'Clients cannot bypass template authorization, alter provenance, or forge receipts');
select extensions.ok((select count(*)=3 and bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('schedule_templates','schedule_template_sources','schedule_template_receipts')), 'All private template tables retain RLS');
select extensions.ok((select count(*)=12 and bool_and(p.prosecdef and 'search_path=""'=any(p.proconfig)) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='public' and p.proname in ('schedule_template_productions','list_schedule_templates','read_schedule_template','mutate_schedule_template','check_schedule_template_request','list_organization_templates','publish_schedule_template')) or (n.nspname='private' and p.proname in ('template_production_actor_can','template_actor_can','template_publication_source_readable','template_actor_can_publish','withdraw_changed_template_publication'))), 'All template security-definer routines pin an empty search path');
select extensions.ok((select count(*)=3 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('service_role',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('review_schedule_template_apply','save_schedule_with_templates','check_schedule_template_save')), 'Apply entrypoints require authenticated per-request authorization');
select extensions.ok((select count(*)=15 and bool_and(not has_function_privilege(r.name,p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join (values('anon'),('authenticated'),('service_role')) r(name) where n.nspname='private' and p.proname in ('template_contexts_allow','schedule_template_bindings_allow','schedule_actor_can_without_template_bindings','schedule_actor_can','template_apply_contexts')), 'Clients cannot bypass the inherited-constraint authorization layer');
select extensions.ok((select count(*)=6 and bool_and(not has_table_privilege(r.name,t.name,'SELECT,INSERT,UPDATE,DELETE')) from (values('private.schedule_template_bindings'),('private.schedule_template_save_receipts')) t(name) cross join (values('anon'),('authenticated'),('service_role')) r(name)), 'Clients cannot remove source constraints or forge Apply save receipts');
select extensions.ok((select count(*)=2 and bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in ('schedule_template_bindings','schedule_template_save_receipts')), 'Apply constraint and receipt tables retain RLS');
select extensions.ok(has_function_privilege('authenticated','public.import_browser_schedule_template(uuid,uuid,uuid,text,text,jsonb,bigint,boolean)','EXECUTE') and not has_function_privilege('anon','public.import_browser_schedule_template(uuid,uuid,uuid,text,text,jsonb,bigint,boolean)','EXECUTE') and not has_function_privilege('service_role','public.import_browser_schedule_template(uuid,uuid,uuid,text,text,jsonb,bigint,boolean)','EXECUTE'), 'Browser import is authenticated and authorized by its production scope');
select extensions.ok((select bool_and(not has_table_privilege(r.name,'private.schedule_template_browser_origins','SELECT,INSERT,UPDATE,DELETE')) from (values('anon'),('authenticated'),('service_role')) r(name)) and (select relrowsecurity from pg_class where oid='private.schedule_template_browser_origins'::regclass), 'Reviewed browser origin records cannot be forged by clients and retain RLS');
select * from extensions.finish();
rollback;
